import React from "react";
import { COLORS, FONT_DISPLAY } from "../constants/theme";

export default function Marquee() {
  return (
    <div id="marquee" style={{ background: COLORS.verdigris, color: COLORS.boneSoft, overflow: "hidden", padding: "16px 0" }}>
      <div className="marquee-track" style={{ display: "flex", width: "200%", whiteSpace: "nowrap" }}>
        {[0, 1].map((k) => (
          <div key={k} style={{ display: "flex", width: "50%", justifyContent: "space-around" }}>
            {["Reclaimed metal", "Hand-set stones", "Made to order", "Lifetime repair", "Carved, not molded"].map((t) => (
              <span key={t} style={{ fontFamily: FONT_DISPLAY, fontStyle: "italic", fontSize: 20 }}>
                {t}
              </span>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}
